head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDFIS00300_11.xml";
scwin.vKisCd = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // 조회조건 기업코드

/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    scwin.fn_Search();
};


/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
    dts_RelcomMutlTrd.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    if (scwin.vKisCd == "") {
        return false;
    }
    return true;
};


/**
 * 담보및지급보증 조회
 */
scwin.fn_Search = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_RelcomMutlTrd);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamic" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.fis.select.coltrlGrt" + "&outputMessageId=FIS_COLTRL_GRT" + "&param01=" + scwin.vKisCd;
    dts_RelcomMutlTrd.DataID = encodeURI(url);
    dts_RelcomMutlTrd.Reset();
};


/**
 * 담보및지급보증 상세 팝업
 */
scwin.fn_RelcomMutlTrdDtlSrchOpen = async function(pRow) {
    fn_GetPar = fn_GetParKey;
    await $c.frame.CreateDialogFrame("RELCOM_MUTL_TRD_DTL", "./ULDFIS00300_P7.gfm", "담보및보증내역 검색", 100, 100, 850 + 20, 840 + 40, "window");
};


/**RETI_PAY_ALWNC_DTL
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKey = function(arrPar) {
    var nRow = dts_RelcomMutlTrd.getRowPosition();
    arrPar[0] = dts_RelcomMutlTrd.getCellData(nRow, "COM_CD");
    arrPar[1] = dts_RelcomMutlTrd.getCellData(nRow, "BAS_YYMM");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};


/**
 *  엑셀파일다운로드
 */
scwin.fn_excel_download = function() {
    if (dts_RelcomMutlTrd.getTotalRow() <= 0) {
        $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_RelcomMutlTrd, "담보및지급보증", "", "8");
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_RelcomMutlTrd_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_RelcomMutlTrd);
    $c.stf.alert_error(dts_RelcomMutlTrd);
};
scwin.dts_RelcomMutlTrd_OnLoadCompleted = function(rowcount) {
    if (dts_RelcomMutlTrd.errorMsg) {
        $c.win.alert(dts_RelcomMutlTrd.errorMsg);
    }
    $c.cm.CloseWin(rowcount, grd_RelcomMutlTrd);
};
scwin.grd_RelcomMutlTrd_OnDblClick = function(row, colid) {
    if (colid == "BAS_YYMM") {
        // 담보및보증내역 상세  팝업 오픈
        scwin.fn_RelcomMutlTrdDtlSrchOpen(row);
    }
};
